  p.wait_for_function('document.getElementById("mapListenStatus").textContent.includes("s")');p.locator('[data-match-stop]').first.click();ok('Audition stops and no clock remains running',p.evaluate('!PulseApp.mappingListening&&!PulseApp.audio.playing'))
