  p.locator('[data-match-copy]').first.click();idle();ok('Rejected copy preserves both charts collections',p.evaluate('JSON.stringify(target26.charts)===targetCharts26&&JSON.stringify(source26.charts)===sourceCharts26'))
  ok('Rejected copy leaves retryable dialog',p.locator('[data-match-copy]').first.is_visible())
