  p.evaluate('PulseApp.showView("settings");window.acousticPreference26=PulseApp.settings.audioMatchImport;window.prefPut26=PulseApp.store.put;PulseApp.store.put=async()=>{throw Error("QA26 preference denied")};void 0;');p.locator('#audioMatchImport26').uncheck();idle()
  ok('Rejected acoustic opt-out restores visible checkbox',p.locator('#audioMatchImport26').is_checked())
