  close();p.evaluate('PulseApp.showView("settings")');p.locator('#audioMatchImport26').check();idle()
  # Facial recovery: initialize a real model, but do not save the previewed face to the song.
  p.evaluate('async()=>await PulseApp.selectSong(target26.id)');p.evaluate('PulseApp.showView("wardrobe");document.getElementById("mmdPanel").open=true')
  p.locator('#mmdInput').set_input_files(str(R/'examples/v25/FACE_ROBOT.pmx'));p.wait_for_selector('#miCommit');idle();p.locator('#miCommit').click();idle();p.wait_for_function('PulseApp.stage.director?.models.length===1')
  face();p.evaluate('window.savedFace26=JSON.stringify(PulseApp.song.scene.faceTrack||null);window.facialSong26=PulseApp.song.id;window.chartFace26=JSON.stringify(PulseApp.song.charts)')
  p.locator('#faceGuide25').set_input_files(str(R/'examples/v25/VOIX_SYNTHETIQUE_TEST.wav'));idle();p.evaluate('async()=>await PulseApp.faceDraftWrite')
  ok('Guide analysis creates a separate facial recovery',p.evaluate('PulseApp.faceRecoveries.has(facialSong26)'))
  ok('Recovery commit has not changed saved scene',p.evaluate('JSON.stringify(PulseApp.song.scene.faceTrack||null)===savedFace26'))
  p.locator('#faceCursor25').fill('1.25');p.locator('#faceCursor25').dispatch_event('input');p.wait_for_function('PulseApp.stage.director.models[0].faceDiagnostic?.open>.1')
  ok('Actual renderer uses recovered facial preview',p.evaluate('PulseApp.stage.director.models[0].faceDiagnostic.open>.1'))
  p.locator('#faceCancel25').click();face();p.wait_for_selector('#faceRecover26')
  ok('Closing and reopening offers recovery explicitly',p.locator('#faceRecover26').is_visible())
  ok('Opening editor did not apply recovered face automatically',p.evaluate('JSON.stringify(PulseApp.stage.faceTrack||null)===savedFace26'))
  p.locator('#faceRecover26').click();ok('Explicit recovery restores guide and controls',p.locator('#faceMode25').input_value()=='audio')
  p.locator('#faceGain25').fill('1.7');p.locator('#faceGain25').dispatch_event('input');p.evaluate('async()=>await PulseApp.faceDraftWrite')
  p.screenshot(path=str(Q/'03-face-recovery.png'))
  # Make all persistence fail; a new voice guide and latest draft must still export.
  p.evaluate('window.atomic26=PulseApp.store.atomic;PulseApp.store.atomic=async()=>{throw Error("QA26 face write denied")};void 0;')
  p.locator('#faceGuide25').set_input_files(str(R/'examples/v26/ECHOS_ORIGINAL.wav'));idle();p.evaluate('async()=>await PulseApp.faceDraftWrite')
  ok('Rejected autosave keeps current recovery and guide in memory',p.evaluate('PulseApp.faceRecoveries.get(facialSong26).track.sourceName==="ECHOS_ORIGINAL.wav"&&PulseApp.facePendingAssets.size>0'))
  ok('Rejected recovery write is visible, not a success badge','refusée' in p.locator('#faceDraftStatus26').inner_text())
  p.evaluate('window.pendingVoice26=PulseApp.faceRecoveries.get(facialSong26).track.sourceAsset')
  ok('New refused guide is not incorrectly claimed as stored',p.evaluate('async()=>!(await PulseApp.store.get("assets",pendingVoice26))'))
  p.locator('#faceSave25').click();idle();ok('Rejected save keeps original face and retryable controls',p.evaluate('JSON.stringify(PulseApp.song.scene.faceTrack||null)===savedFace26') and p.locator('#faceSave25').is_visible())
  close();p.evaluate('PulseApp.showView("settings")')
  with p.expect_download(timeout=60000) as dl:p.locator('#bundleExport25').click();idle()
  bundle=Q/'facial-rescue.pulsebundle';dl.value.save_as(bundle)
  ok('Binary rescue export succeeds while writes are refused',bundle.is_file())
  data=p.evaluate('async()=>{const p=await PulseApp.buildBackupData();return {drafts:p.data.faceDrafts,assets:p.assets.map(x=>x.id)}}')
  ok('Rescue contains latest guide that never reached storage',any(d['track']['sourceAsset']==p.evaluate('pendingVoice26') for d in data['drafts']) and p.evaluate('pendingVoice26') in data['assets'])
  ok('Facial draft changes never modified rhythm notes',p.evaluate('JSON.stringify(PulseApp.song.charts)===chartFace26'))
  p.evaluate('PulseApp.store.atomic=atomic26;window.restoreCount26=PulseApp.songs.length;void 0;');p.locator('#backupInput').set_input_files(str(bundle));idle();p.locator('#confirmRestore').click();idle()
  ok('Backup restores songs in copies',p.evaluate('PulseApp.songs.length===restoreCount26*2'))
  p.evaluate('''async()=>{window.restoredDraft26=(await PulseApp.store.all('settings')).find(d=>d.id.startsWith('face-draft:')&&!d.discarded&&d.songId!==facialSong26&&d.track?.sourceName==='ECHOS_ORIGINAL.wav');await PulseApp.selectSong(restoredDraft26.songId);}''')
  ok('Restoration remaps recovery owner and unsaved guide ID',p.evaluate('restoredDraft26.songId!==facialSong26&&restoredDraft26.track.sourceAsset!==pendingVoice26'))
