  face();p.wait_for_selector('#faceRecover26');p.locator('#faceRecover26').click();ok('Restored draft can be explicitly resumed',p.locator('#faceGain25').input_value()=='1.7')
  p.locator('#faceSave25').click();idle();ok('Confirmed facial save publishes the recovered scene',p.evaluate('PulseApp.song.scene.faceTrack?.gain===1.7'))
  ok('Saved scene and cleared recovery commit together',p.evaluate('async()=>(await PulseApp.store.get("settings","face-draft:"+PulseApp.song.id)).discarded===true'))
  face();ok('Saved recovery is not offered again',not p.locator('#faceRecovery26').is_visible())
  p.locator('#faceGain25').fill('1.2');p.locator('#faceGain25').dispatch_event('input');p.evaluate('async()=>await PulseApp.faceDraftWrite');close();face();p.wait_for_selector('#faceRecover26');p.locator('#faceDiscard26').click();idle();ok('Discarding recovery does not touch saved face',p.evaluate('PulseApp.song.scene.faceTrack.gain===1.7'))
  ok('Discarded recovery not offered after reopening',not p.locator('#faceRecovery26').is_visible());p.set_viewport_size({'width':390,'height':844});p.screenshot(path=str(Q/'04-mobile-face.png'))
  # Corrupt draft metadata refused before any confirmation or write.
